// v16.xx (coop11), HIS ORDER (2026-10-14), the two player first: THE DIRECTOR WATCHES BOTH PLAYERS. It read the stress from the host player alone: a hurt player 2 never gave him a breather, a pack hunting
// player 2 alone did not count as a fight, and a quiet stretch for the host while player 2 was being chased still swelled the waves and could call an ambush. The health a teammate has just lost (his
// state word, the health and the most of it he sends ten times a second) now adds to the stress the way the host player's does, a body hunting a teammate within 700 counts as a fight, and a teammate
// hurt in the last few seconds ends the quiet stretch. The waves still land near whoever is picked (that was already for both).
function flowMates(){
  var out=[], i, g;
  if(typeof NET!=='object'||!NET||!NET.on||!Array.isArray(NET.up)||typeof netUpShown!=='function') return out;
  for(i=0;i<NET.up.length;i++){ g=NET.up[i]; if(g&&g.seat!==NET.seat&&netUpShown(g)&&!g.dn) out.push(g); }
  return out;
}
function flowMateLoss(D){
  var M=flowMates(), i, g, k, prev, lost=0, t=G.t||0;
  D.mhp=D.mhp||{};
  for(i=0;i<M.length;i++){
    g=M[i]; k='s'+g.seat; prev=D.mhp[k];
    if(typeof prev==='number'&&+g.hp<prev){ lost+=(prev-(+g.hp))/Math.max(40,+g.mh||100)*2.2; D.mAt=t; }
    D.mhp[k]=+g.hp;
  }
  D.mhurt=(t-(+D.mAt||-999)<4)?1:0;
  return lost;
}
function flowNearMate(e,r){
  var M=flowMates(), i;
  for(i=0;i<M.length;i++) if(dist(e,M[i])<r) return true;
  return false;
}
// FLOW-MODULE-END (the next flow builds add their code above this line)

